    @inline(__always)
    private func checkMinimumMagnitudeConstantAAlternating(_ even: Lane, _ odd: Lane) {
        let mismatches = Mismatches("minimumMagnitude with a alternating \(hex(even)), \(hex(odd))")
        let bInputs = Inputs.vectors(H.self, seed: 0x1F99_277D_1982_B1AF)
        mismatches.check(
            H.repeatingBlock(even, odd, even, odd, even, odd, even, odd),
            H(
                raw: HighwayReference.repeatingBlockF16(
                    even.bitPattern,
                    odd.bitPattern,
                    even.bitPattern,
                    odd.bitPattern,
                    even.bitPattern,
                    odd.bitPattern,
                    even.bitPattern,
                    odd.bitPattern
                )
            ),
            "repeatingBlock"
        )
        for b in bInputs
        where !hasUnorderedNaNs(
            H.repeatingBlock(even, odd, even, odd, even, odd, even, odd).simd,
            b.simd
        ) {
            mismatches.check(
                H.minimumMagnitude(H.repeatingBlock(even, odd, even, odd, even, odd, even, odd), b),
                H(
                    raw: HighwayReference.minimumMagnitudeF16(
                        H.repeatingBlock(even, odd, even, odd, even, odd, even, odd).raw,
                        b.raw
                    )
                ),
                "b: \(describe(b))"
            )
        }
        mismatches.record()
    }

